inline const RecoveredActivityMaskRead* findActivityMaskRead(u32 callVa) {
    for (const auto& row : kRecoveredActivityMaskReads)
        if (row.callVa == callVa) return &row;
    return nullptr;
}

inline std::size_t countActivityMaskReads(
    ActivityMaskReadKind kind) {
    std::size_t count = 0;
    for (const auto& row : kRecoveredActivityMaskReads)
        if (row.kind == kind) ++count;
    return count;
}

// Mirrors the recovered test form only. Dynamic operands are
// supplied by the caller; a zero dynamic mask cannot satisfy an
// intersection or equality test.
inline bool evaluateActivityMaskRead(
    const RecoveredActivityMaskRead& row, u32 activityMask,
    u32 dynamicMask = 0) {
    switch (row.kind) {
    case ActivityMaskReadKind::Equal:
        return activityMask == row.mask;
    case ActivityMaskReadKind::Bit:
        return (activityMask & row.mask) != 0;
    case ActivityMaskReadKind::Intersect:
        return dynamicMask != 0 &&
               (activityMask & dynamicMask) != 0;
    case ActivityMaskReadKind::DynamicEqual:
        return dynamicMask != 0 && activityMask == dynamicMask;
    case ActivityMaskReadKind::NonZero:
        return activityMask != 0;
    case ActivityMaskReadKind::Unknown:
        break;
    }
    return false;
}

